/* Independent pose editor; generation continues through the shared Demo candidate flow. */
'use strict';
const poseBaseHtml=canvasNodeToolHtml,poseBaseAction=handleCanvasNodeToolAction,poseBaseExecution=canvasToolExecution;
canvasToolNames.pose='姿态调整';canvasToolDefaults.pose={locked:true,protectStyle:true,protectBackground:true};
let posePointer=null;
function poseCurrent(n){return poseValues(canvasToolValues(n,'pose'));}
function poseSvg(d){const p=d.joints,rig=Object.entries(poseParents).map(([key,parent])=>`<line x1="${p[key][0]}" y1="${p[key][1]}" x2="${p[parent][0]}" y2="${p[parent][1]}"/>`).join(''),lines=Object.entries(poseParents).map(([key,parent])=>`<line x1="${p[key][0]}" y1="${p[key][1]}" x2="${p[parent][0]}" y2="${p[parent][1]}" stroke-width="${/Ankle|Knee|Hip/.test(key)?14:/Shoulder|Elbow|Wrist/.test(key)?12:10}"/>`).join('');return `<svg class="pose-stage" viewBox="0 0 520 236" role="group" aria-label="人物姿态关节"><rect width="520" height="236" rx="11" fill="#020203"/><ellipse cx="${(p.leftAnkle[0]+p.rightAnkle[0])/2}" cy="${(p.leftAnkle[1]+p.rightAnkle[1])/2+7}" rx="43" ry="6" fill="#000" opacity=".58"/><g stroke="#48484d" opacity=".92" stroke-linecap="round">${lines}</g><path fill="#000" d="M${p.leftShoulder} Q${p.neck[0]},${p.neck[1]-7} ${p.rightShoulder} L${p.rightHip[0]+5},${p.rightHip[1]-2} Q${p.hip[0]},${p.hip[1]+7} ${p.leftHip[0]-5},${p.leftHip[1]-2} Z"/><circle cx="${p.head[0]}" cy="${p.head[1]}" r="14.5" fill="#000"/>${['leftAnkle','rightAnkle'].map(key=>`<path d="M${p[key][0]-8},${p[key][1]+5} h17" stroke="#48484d" stroke-width="8" stroke-linecap="round"/>`).join('')}<g stroke="#a0a0a6" stroke-width="3.5" stroke-linecap="round" opacity=".72">${rig}</g>${Object.entries(p).map(([key,[x,y]])=>`<g class="pose-joint" data-pose-joint="${key}" role="button" tabindex="0" aria-label="${poseLabels[key]}关节" aria-description="方向键微调，Shift 加速" transform="translate(${x} ${y})"><title>${poseLabels[key]}</title><circle class="pose-hit" r="15" fill="transparent"/><circle class="pose-focus" r="9" fill="none" stroke="#ddd"/><circle r="5.2" fill="#f4f4f5"/></g>`).join('')}</svg>`;}
function poseHtml(n){const d=poseCurrent(n);return `<section class="canvas-creation node-tool-panel pose-panel" role="dialog" aria-label="人物调节 · 姿态调整" data-creation-node="${n.id}"><header class="pose-header"><div><strong>姿态调整</strong><p>改变选中单张人物的内容，其余不变</p></div>${iconBtn('关闭姿态调整','canvas-tool-close','close')}</header><main class="pose-main"><section class="pose-card"><header><div class="pose-title-group"><strong>姿态控制</strong><label>比例锁定<input type="checkbox" role="switch" aria-label="比例锁定" data-pose-field="locked" ${d.locked?'checked':''}></label></div><button data-action="pose-reset">${I('rotate')}重置</button></header><div class="pose-preview">${poseSvg(d)}<small>拖动关节点调整人物姿态</small></div></section></main><footer class="appearance-footer"><details class="canvas-tool-menu appearance-protections"><summary role="button">${I('shield')}${d.protectStyle&&d.protectBackground?'已启用全部保护项':'保护项设置'}</summary><div><strong>保护项选择</strong><p>开启后对参考图背景或风格不进行改动</p>${[['protectStyle','风格保护'],['protectBackground','背景保护']].map(([key,label])=>`<label>${label}<input type="checkbox" role="switch" aria-label="${label}" data-pose-field="${key}" ${d[key]?'checked':''}></label>`).join('')}</div></details><span class="creation-spacer"></span><button disabled>2K ${I('down')}</button><button disabled>1X ${I('down')}</button><small>示例 · 不计费</small><button class="creation-submit" aria-label="提交创作" data-action="canvas-creation-submit" ${poseChanged(d)?'':'disabled'}>${I('arrowup')}</button></footer></section>`;}
canvasNodeToolHtml=function(n){return canvasActiveTool?.type==='pose'?poseHtml(n):poseBaseHtml(n);};
handleCanvasNodeToolAction=function(action){if(action==='pose-reset'){const n=canvasCreationNode();if(n&&canvasActiveTool?.type==='pose'){storeCanvasToolValue(n,'pose','joints',poseValues().joints);refreshCanvasCreation();positionCanvasNodeOverlays();}return true;}if(action==='canvas-tool-close'||action.startsWith('canvas-tool-open:'))posePointer=null;return poseBaseAction(action);};
canvasToolExecution=function(n){if(canvasActiveTool?.type!=='pose')return poseBaseExecution(n);const settings=poseSnapshot(poseCurrent(n));return {name:'姿态调整',settings,mediaSettings:{resolution:'2K'},prompt:`姿态调整 · ${n.title}。${settings.protectStyle?'保持风格。':''}${settings.protectBackground?'保持背景。':''}按指定骨架调整选中人物。`};};
function poseEdit(n,key,point){const next=poseMove(poseCurrent(n),key,point);storeCanvasToolValue(n,'pose','joints',next.joints);const stage=document.querySelector('.pose-stage');if(stage){const holder=document.createElement('div');holder.innerHTML=poseSvg(next);const replacement=holder.firstElementChild;stage.querySelectorAll('[data-pose-joint]').forEach(el=>el.setAttribute('transform',replacement.querySelector(`[data-pose-joint="${el.dataset.poseJoint}"]`).getAttribute('transform')));for(const el of [...stage.children])if(!el.matches('.pose-joint'))el.remove();for(const el of [...replacement.children].filter(el=>!el.matches('.pose-joint')).reverse())stage.prepend(el);document.querySelector('.pose-panel .creation-submit').disabled=!poseChanged(next);}}
function posePoint(event,stage){const matrix=stage.getScreenCTM();if(!matrix)return null;const point=new DOMPoint(event.clientX,event.clientY).matrixTransform(matrix.inverse());return [point.x,point.y];}
document.addEventListener('pointerdown',event=>{const joint=event.target.closest?.('[data-pose-joint]');if(!joint||event.button!==0)return;const n=canvasCreationNode();if(!n||canvasActiveTool?.type!=='pose')return;const stage=joint.closest('.pose-stage'),point=posePoint(event,stage),key=point?poseNearestJoint(poseCurrent(n),point):joint.dataset.poseJoint,selected=stage.querySelector(`[data-pose-joint="${key}"]`);posePointer={nodeId:n.id,key,pointerId:event.pointerId};selected.setPointerCapture(event.pointerId);selected.focus({preventScroll:true});event.preventDefault();event.stopPropagation();});
document.addEventListener('pointermove',event=>{if(!posePointer||event.pointerId!==posePointer.pointerId)return;const n=canvasCreationNode(),stage=document.querySelector('.pose-stage');if(n?.id!==posePointer.nodeId||!stage){posePointer=null;return;}const point=posePoint(event,stage);if(point)poseEdit(n,posePointer.key,point);});
for(const type of ['pointerup','pointercancel','lostpointercapture'])document.addEventListener(type,()=>{posePointer=null;});
document.addEventListener('keydown',event=>{const joint=event.target.closest?.('[data-pose-joint]');if(!joint||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key))return;const n=canvasCreationNode();if(!n||canvasActiveTool?.type!=='pose')return;const point=poseCurrent(n).joints[joint.dataset.poseJoint],step=event.shiftKey?8:2;poseEdit(n,joint.dataset.poseJoint,[point[0]+(event.key==='ArrowLeft'?-step:event.key==='ArrowRight'?step:0),point[1]+(event.key==='ArrowUp'?-step:event.key==='ArrowDown'?step:0)]);event.preventDefault();event.stopImmediatePropagation();},true);
document.addEventListener('change',event=>{const field=event.target.dataset.poseField,n=canvasCreationNode();if(!field||!n||canvasActiveTool?.type!=='pose')return;storeCanvasToolValue(n,'pose',field,event.target.checked);if(field!=='locked'){const d=poseCurrent(n);document.querySelector('.pose-panel .appearance-protections summary').innerHTML=I('shield')+(d.protectStyle&&d.protectBackground?'已启用全部保护项':'保护项设置');}});
render();
